shell_commands.command:
cd /testbed && git apply --recount <<'PATCH'
diff --git a/tests/unit/cluster/cluster-shards.tcl b/tests/unit/cluster/cluster-shards.tcl
new file mode 100644
--- /dev/null
+++ b/tests/unit/cluster/cluster-shards.tcl
@@ -0,0 +1,1 @@
+proc cluster_allocate_shards_test_slots {masters replicas} {
+    R 0 cluster addslotsrange 0 1000 1002 5461
+    R 1 cluster addslotsrange 1001 1001 5462 10922
+    R 2 cluster addslotsrange 10923 16383
+}
+
+proc assert_cluster_shards_slots {reference expected} {
+    set actual [dict create]
+    set shards [R $reference cluster shards]
+    assert_equal 3 [llength $shards]
+    foreach shard $shards {
+        foreach node [dict get $shard nodes] {
+            dict set actual [dict get $node id] [dict get $shard slots]
+        }
+    }
+    assert_equal [lsort [dict keys $expected]] [lsort [dict keys $actual]]
+    dict for {id slots} $expected {
+        assert_equal $slots [dict get $actual $id]
+    }
+}
+
+start_cluster 3 3 {tags {external:skip cluster}} {
+    set expected [dict create]
+    set ranges {{0 1000 1002 5461} {1001 1001 5462 10922} {10923 16383}}
+    for {set j 0} {$j < 6} {incr j} {
+        dict set expected [R $j cluster myid] [lindex $ranges [expr {$j % 3}]]
+    }
+    set old_primary_id [R 0 cluster myid]
+    set new_primary_id [R 3 cluster myid]
+
+    test "CLUSTER SHARDS reports continuous and split slot ranges" {
+        for {set j 0} {$j < 6} {incr j} {
+            assert_cluster_shards_slots $j $expected
+        }
+    }
+
+    set paused_pid [srv 0 pid]
+    test "Fail over a shard while its primary is unreachable" {
+        pause_process $paused_pid
+        wait_for_condition 1000 50 {
+            [s -3 role] eq {master}
+        } else {
+            fail "Replica did not become a primary"
+        }
+        for {set j 1} {$j < 6} {incr j} {
+            wait_for_condition 1000 50 {
+                [lindex [R $j cluster slots] 0 2 2] eq $new_primary_id
+            } else {
+                fail "Cluster node $j did not learn the new slot owner"
+            }
+        }
+    }
+
+    test "CLUSTER SHARDS preserves slots with an unreachable former primary" {
+        for {set j 1} {$j < 6} {incr j} {
+            set old_primary [cluster_get_node_by_id $j $old_primary_id]
+            assert {[cluster_has_flag $old_primary master]}
+            assert {[cluster_has_flag $old_primary fail]}
+            assert_cluster_shards_slots $j $expected
+            assert_cluster_shards_slots $j $expected
+        }
+    }
+
+    test "CLUSTER SHARDS preserves slots after the former primary rejoins" {
+        resume_process $paused_pid
+        wait_for_condition 1000 50 {
+            [s 0 role] eq {slave}
+        } else {
+            fail "Former primary did not become a replica"
+        }
+        wait_for_cluster_propagation
+        for {set j 0} {$j < 6} {incr j} {
+            assert_cluster_shards_slots $j $expected
+        }
+    }
+
+    test "CLUSTER SHARDS returns empty slots only for a slotless shard" {
+        R 2 cluster delslotsrange 10923 16383
+        dict set expected [R 2 cluster myid] {}
+        dict set expected [R 5 cluster myid] {}
+        assert_cluster_shards_slots 2 $expected
+    }
+} cluster_allocate_shards_test_slots
