--- a/src/cluster_legacy.c
+++ b/src/cluster_legacy.c
@@ -5663,26 +5663,30 @@
-/* Add the shard reply of a single shard based off the given primary node. */
+/* Add the shard reply of a single shard based on its member nodes. */
 void addShardReplyForClusterShards(client *c, list *nodes) {
     serverAssert(listLength(nodes) > 0);
-    clusterNode *n = listNodeValue(listFirst(nodes));
     addReplyMapLen(c, 2);
     addReplyBulkCString(c, "slots");

-    /* Use slot_info_pairs from the primary only */
-    n = clusterNodeGetPrimary(n);
-
-    if (n->slot_info_pairs != NULL) {
+    /* During failover, a shard may contain both the slotless former primary
+     * and the new primary. Use the slot ranges of all members, not the role
+     * or position of a node in the list, to determine the shard's slots. */
+    void *slot_replylen = addReplyDeferredLen(c);
+    int slot_reply_count = 0;
+    listIter li;
+    listRewind(nodes, &li);
+    for (listNode *ln = listNext(&li); ln != NULL; ln = listNext(&li)) {
+        clusterNode *n = listNodeValue(ln);
         serverAssert((n->slot_info_pairs_count % 2) == 0);
-        addReplyArrayLen(c, n->slot_info_pairs_count);
         for (int i = 0; i < n->slot_info_pairs_count; i++) addReplyLongLong(c, (unsigned long)n->slot_info_pairs[i]);
-    } else {
-        /* If no slot info pair is provided, the node owns no slots */
-        addReplyArrayLen(c, 0);
+        slot_reply_count += n->slot_info_pairs_count;
     }
+    setDeferredArrayLen(c, slot_replylen, slot_reply_count);

     addReplyBulkCString(c, "nodes");
     addReplyArrayLen(c, listLength(nodes));
-    listIter li;
     listRewind(nodes, &li);
     for (listNode *ln = listNext(&li); ln != NULL; ln = listNext(&li)) {
