+                        "description": "An even number element array specifying the start and end slot numbers for slot ranges owned by this shard. An empty array means that no node in the shard has slots assigned.",
                         "type": "array",
diff --git a/tests/unit/cluster/cluster-shards.tcl b/tests/unit/cluster/cluster-shards.tcl
--- a/tests/unit/cluster/cluster-shards.tcl
+++ b/tests/unit/cluster/cluster-shards.tcl
@@ -59,6 +59,7 @@
             assert {[cluster_has_flag $old_primary master]}
             assert {[cluster_has_flag $old_primary fail]}
             assert_cluster_shards_slots $j $expected
+            # Repeated requests must not retain cached slot ranges.
             assert_cluster_shards_slots $j $expected
